# Try pattern completion hypothesis
grid = [
    [0, 9, 3, 3, 1, 5],
    [7, 5, 3, 3, 1, 7],
    [3, 3, 3, 3, 9, 2],
    [2, 4, 0, 7, 3, 3],
    [4, 3, 5, 3, 3, 3],
    [3, 3, 3, 3, 3, 3]
]

# Look at specific positions that might be patterns
# For example, check if grid[r][c] == grid[5-r][c] (vertical reflection symmetry)
print("Vertical symmetry check:")
for r in range(6):
    for c in range(6):
        if grid[r][c] != 3 and grid[5-r][c] != 3:
            sym = "MATCH" if grid[r][c] == grid[5-r][c] else "DIFFER"
            print(f"({r},{c})={grid[r][c]} vs ({5-r},{c})={grid[5-r][c]}: {sym}")

# Hypothesis: output shows which cells are vertically symmetric
output8 = []
for r in range(6):
    row = []
    for c in range(6):
        if grid[r][c] == 3:
            row.append(3)
        elif grid[5-r][c] == 3 or grid[r][c] != grid[5-r][c]:
            row.append(0)  # broken symmetry
        else:
            row.append(grid[r][c])
    output8.append(row)

print("\nHypothesis: Symmetric pairs keep value, others become 0")
for row in output8:
    print(row)

action = {"action": "submit", "grid": output8}
print(json.dumps(action))

# Try neighbor count hypothesis
grid = [
    [0, 9, 3, 3, 1, 5],
    [7, 5, 3, 3, 1, 7],
    [3, 3, 3, 3, 9, 2],
    [2, 4, 0, 7, 3, 3],
    [4, 3, 5, 3, 3, 3],
    [3, 3, 3, 3, 3, 3]
]

# Count how many non-3 neighbors each cell has
def count_non3_neighbors(grid, r, c):
    count = 0
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < 6 and 0 <= nc < 6:
                if grid[nr][nc] != 3:
                    count += 1
    return count

output9 = [[count_non3_neighbors(grid, r, c) for c in range(6)] for r in range(6)]
print("Non-3 neighbor counts:")
for row in output9:
    print(row)

action = {"action": "submit", "grid": output9}
print(json.dumps(action))

# Hypothesis: Output marks regions uniquely, maybe by counting their size
grid = [
    [0, 9, 3, 3, 1, 5],
    [7, 5, 3, 3, 1, 7],
    [3, 3, 3, 3, 9, 2],
    [2, 4, 0, 7, 3, 3],
    [4, 3, 5, 3, 3, 3],
    [3, 3, 3, 3, 3, 3]
]

background = 3
visited = [[False]*6 for _ in range(6)]
regions_by_value = {}
region_size_map = {}

for r in range(6):
    for c in range(6):
        if visited[r][c]:
            continue
        if grid[r][c] == background:
            continue

        # BFS
        q = [(r,c)]
        visited[r][c] = True
        region = set()

        while q:
            cr, cc = q.pop(0)
            region.add((cr, cc))

            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < 6 and 0 <= nc < 6:
                    if not visited[nr][nc] and grid[nr][nc] == grid[cr][cc]:
                        visited[nr][nc] = True
                        q.append((nr, nc))

        val = grid[r][c]
        region_size = len(region)
        regions_by_value.setdefault(val, []).append(region)
        region_size_map[(r,c)] = region_size

print("Region sizes:")
for pos, size in sorted(region_size_map.items()):
    print(f"{pos}: {size}")

# Output could show region size instead of value
output10 = [[region_size_map.get((r,c), background) for c in range(6)] for r in range(6)]
print("\nHypothesis: Replace cell with its region size")
for row in output10:
    print(row)

action = {"action": "submit", "grid": output10}
print(json.dumps(action))

